\begin{theorem}
$\lim_{n \to \infty} \frac{1}{n} = 0$.
\end{theorem}

\begin{proof}
Let $\varepsilon > 0$. Choose $N \in \mathbb{N}$ with $N > \frac{1}{\varepsilon}$.
For all $n \geq N$,
\begin{align}
  \left| \frac{1}{n} - 0 \right| &= \frac{1}{n} \leq \frac{1}{N} < \varepsilon,
\end{align}
hence the limit is $0$.
\end{proof}
